_ENV_PY_RE = re.compile(r"os\.environ(?:\.get)?\(\s*['\"](\w+)['\"]|os\.getenv\(\s*['\"](\w+)['\"]")
_ENV_NODE_RE = re.compile(r"process\.env\.(\w+)")
